CREATE TABLE app_users (id BIGINT PRIMARY KEY AUTO_INCREMENT, email VARCHAR(190) NOT NULL UNIQUE, display_name VARCHAR(120) NOT NULL, password_hash VARCHAR(255) NOT NULL, role VARCHAR(24) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE forms (id BIGINT PRIMARY KEY AUTO_INCREMENT, slug VARCHAR(120) NOT NULL UNIQUE, created_by BIGINT NOT NULL, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), CONSTRAINT fk_forms_creator FOREIGN KEY (created_by) REFERENCES app_users(id));
CREATE TABLE form_versions (id BIGINT PRIMARY KEY AUTO_INCREMENT, form_id BIGINT NOT NULL, version_number INT NOT NULL, title VARCHAR(160) NOT NULL, description VARCHAR(600), status VARCHAR(24) NOT NULL, published_at TIMESTAMP(6) NULL, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), CONSTRAINT uq_form_version UNIQUE (form_id, version_number), CONSTRAINT fk_versions_form FOREIGN KEY (form_id) REFERENCES forms(id) ON DELETE CASCADE, INDEX idx_versions_status (status), INDEX idx_versions_form_status (form_id, status));
CREATE TABLE form_fields (id BIGINT PRIMARY KEY AUTO_INCREMENT, form_version_id BIGINT NOT NULL, field_key VARCHAR(80) NOT NULL, label VARCHAR(140) NOT NULL, description VARCHAR(300), field_type VARCHAR(24) NOT NULL, required BOOLEAN NOT NULL DEFAULT FALSE, position_index INT NOT NULL, CONSTRAINT uq_version_field_key UNIQUE (form_version_id, field_key), CONSTRAINT fk_fields_version FOREIGN KEY (form_version_id) REFERENCES form_versions(id) ON DELETE CASCADE);
CREATE TABLE field_options (id BIGINT PRIMARY KEY AUTO_INCREMENT, field_id BIGINT NOT NULL, option_value VARCHAR(180) NOT NULL, position_index INT NOT NULL, CONSTRAINT fk_options_field FOREIGN KEY (field_id) REFERENCES form_fields(id) ON DELETE CASCADE);
CREATE TABLE submissions (id BIGINT PRIMARY KEY AUTO_INCREMENT, reference_code VARCHAR(32) NOT NULL UNIQUE, form_version_id BIGINT NOT NULL, requester_id BIGINT NOT NULL, status VARCHAR(24) NOT NULL, rejection_comment VARCHAR(1000), submitted_at TIMESTAMP(6) NULL, reviewed_at TIMESTAMP(6) NULL, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), row_version BIGINT NOT NULL DEFAULT 0, CONSTRAINT fk_submissions_version FOREIGN KEY (form_version_id) REFERENCES form_versions(id), CONSTRAINT fk_submissions_requester FOREIGN KEY (requester_id) REFERENCES app_users(id), INDEX idx_submissions_status (status), INDEX idx_submissions_requester_status (requester_id, status), INDEX idx_submissions_updated (updated_at));
CREATE TABLE submission_answers (id BIGINT PRIMARY KEY AUTO_INCREMENT, submission_id BIGINT NOT NULL, field_id BIGINT NOT NULL, answer_value TEXT, CONSTRAINT uq_submission_field UNIQUE (submission_id, field_id), CONSTRAINT fk_answers_submission FOREIGN KEY (submission_id) REFERENCES submissions(id) ON DELETE CASCADE, CONSTRAINT fk_answers_field FOREIGN KEY (field_id) REFERENCES form_fields(id));
CREATE TABLE workflow_events (id BIGINT PRIMARY KEY AUTO_INCREMENT, submission_id BIGINT NOT NULL, actor_id BIGINT NOT NULL, action VARCHAR(32) NOT NULL, from_status VARCHAR(24), to_status VARCHAR(24) NOT NULL, comment VARCHAR(1000), created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), CONSTRAINT fk_events_submission FOREIGN KEY (submission_id) REFERENCES submissions(id) ON DELETE CASCADE, CONSTRAINT fk_events_actor FOREIGN KEY (actor_id) REFERENCES app_users(id), INDEX idx_events_submission_created (submission_id, created_at));
